import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import type { DiscoveredModule } from './modules.ts';

/**
 * Write the Lambda entry for an API group: it imports the group's module
 * routes and hands them to @bar/server. Modules contain no infra code; this
 * generated file is the only glue.
 */
export function writeGroupEntry(
  dir: string,
  name: string,
  modules: readonly DiscoveredModule[],
): string {
  mkdirSync(dir, { recursive: true });
  const imports = modules
    .filter((module) => module.manifest.routes)
    .map((module, i) => ({
      id: `routes${i}`,
      name: module.manifest.name,
      path: join(module.dir, 'src/routes.ts'),
    }));
  const source = [
    '// Generated by infra at synth time. Do not edit.',
    "import { createApiHandler } from '@bar/server/lambda';",
    ...imports.map((i) => `import ${i.id} from ${JSON.stringify(i.path)};`),
    '',
    `export const handler = createApiHandler([${imports
      .map((i) => `{ name: ${JSON.stringify(i.name)}, routes: ${i.id} }`)
      .join(', ')}]);`,
    '',
  ].join('\n');
  const file = join(dir, `${name}.ts`);
  writeFileSync(file, source);
  return file;
}
